import { useEffect, useRef, useCallback } from "react";

/**
 * A hook that manages auto-scrolling for a chat container.
 * It implements "smart stickiness": if the user is at the bottom, it stays at the bottom.
 * If the user scrolls up, it stops auto-scrolling to allow reading history.
 *
 * @param dep - The dependency that triggers a scroll check (e.g. messages array or children).
 * @param options - Configuration options.
 */
export const useChatScroll = <T extends HTMLElement>(
  dep: unknown,
  options: {
    enabled?: boolean;
    threshold?: number;
  } = {},
) => {
  const { enabled = true, threshold = 50 } = options;
  const ref = useRef<T>(null);
  // We use a ref to track if we should auto-scroll, initialized to true (start at bottom)
  const shouldAutoScroll = useRef(true);

  const handleScroll = useCallback(() => {
    if (!ref.current) return;
    const { scrollTop, scrollHeight, clientHeight } = ref.current;
    // Check if the user is close to the bottom
    // We use Math.abs to handle potential floating point precision issues with zoom/display scaling
    const atBottom = Math.abs(scrollHeight - clientHeight - scrollTop) <= threshold;
    shouldAutoScroll.current = atBottom;
  }, [threshold]);

  useEffect(() => {
    const element = ref.current;
    if (!enabled || !element) return;

    // Scroll immediately on dependency change if sticky
    if (shouldAutoScroll.current) {
      element.scrollTop = element.scrollHeight;
    }

    // Observe DOM changes (content loading, expanding steps) to maintain stickiness
    const observer = new MutationObserver(() => {
      if (shouldAutoScroll.current) {
        element.scrollTop = element.scrollHeight;
      }
    });

    observer.observe(element, {
      childList: true,
      subtree: true,
      attributes: true, // In case style/height attributes change
    });

    return () => observer.disconnect();
  }, [dep, enabled]);

  // Force scroll to bottom (programmatic override)
  const scrollToBottom = useCallback(() => {
    if (ref.current) {
      ref.current.scrollTop = ref.current.scrollHeight;
      shouldAutoScroll.current = true;
    }
  }, []);

  return { ref, onScroll: handleScroll, scrollToBottom };
};
